"""Builder-facing button values produced by response source tools."""

from pydantic import BaseModel, ConfigDict


class Button(BaseModel):
    """Describe one button supplied by a response source tool.

    When ``ref`` is set, the engine writes ``value`` to that fully qualified
    memory reference on tap. Without ``ref``, the tap is handled as the plain
    text ``value``, or as ``title`` when ``value`` is omitted.
    """

    model_config = ConfigDict(frozen=True)

    title: str
    value: str | None = None
    ref: str | None = None
